<script setup>
import { onMounted, reactive, ref } from 'vue'
const props=defineProps({api:{type:Function,required:true}})
const tabs=[['nodes','节点'],['groups','权限组'],['routes','线路规则']]
const tab=ref('nodes'),nodes=ref([]),groups=ref([]),routes=ref([]),machines=ref([]),loading=ref(false),error=ref(''),modal=ref(false),saving=ref(false),formError=ref(''),formKind=ref('node'),echNode=ref(null),echKey=ref('')
const node=reactive({id:null,type:'vless',name:'',host:'',port:443,server_port:443,rate:1,group_ids:[],route_ids:[],tags:'[]',excludes:'[]',ips:'[]',enabled:true,show:true,machine_id:'',parent_id:'',transfer_enable:'',code:'',spectific_key:'',protocol_settings:'{}'})
const group=reactive({id:null,name:''})
const route=reactive({id:null,remarks:'',match:'[]',action:'proxy',action_value:''})
const traffic=value=>{const n=Number(value||0);if(n>=1024**3)return `${(n/1024**3).toFixed(2)} GB`;if(n>=1024**2)return `${(n/1024**2).toFixed(2)} MB`;return `${n.toLocaleString()} B`}
const types=['hysteria','vless','trojan','vmess','tuic','shadowsocks','anytls','socks','naive','http','mieru']
const parse=(text,label)=>{try{return JSON.parse(text||'{}')}catch{throw new Error(`${label} JSON 格式不正确。`)}}
async function load(){loading.value=true;error.value='';try{if(tab.value==='nodes'){[nodes.value,groups.value,routes.value,machines.value]=await Promise.all([props.api('server/manage/getNodes'),props.api('server/group/fetch'),props.api('server/route/fetch'),props.api('server/machine/fetch')])}else if(tab.value==='groups')groups.value=await props.api('server/group/fetch');else routes.value=await props.api('server/route/fetch');nodes.value=Array.isArray(nodes.value)?nodes.value:[];groups.value=Array.isArray(groups.value)?groups.value:[];routes.value=Array.isArray(routes.value)?routes.value:[];machines.value=Array.isArray(machines.value)?machines.value:[]}catch(e){error.value=e.message}finally{loading.value=false}}
function changeTab(id){tab.value=id;load()}
function newNode(){Object.assign(node,{id:null,type:'vless',name:'',host:'',port:443,server_port:443,rate:1,group_ids:[],route_ids:[],tags:'[]',excludes:'[]',ips:'[]',enabled:true,show:true,machine_id:'',parent_id:'',transfer_enable:'',code:'',spectific_key:'',protocol_settings:'{}'});formError.value='';formKind.value='node';modal.value=true}
function editNode(item){Object.assign(node,{id:item.id,type:item.type,name:item.name,host:item.host,port:item.port,server_port:item.server_port,rate:item.rate,group_ids:item.group_ids||[],route_ids:item.route_ids||[],tags:JSON.stringify(item.tags||[]),excludes:JSON.stringify(item.excludes||[]),ips:JSON.stringify(item.ips||[]),enabled:Boolean(item.enabled),show:Boolean(item.show),machine_id:item.machine_id??'',parent_id:item.parent_id??'',transfer_enable:item.transfer_enable??'',code:item.code||'',spectific_key:item.spectific_key||'',protocol_settings:JSON.stringify(item.protocol_settings||{},null,2)});formError.value='';formKind.value='node';modal.value=true}
async function saveNode(){saving.value=true;formError.value='';try{const body={id:node.id||undefined,type:node.type,name:node.name,host:node.host,port:Number(node.port),server_port:Number(node.server_port),rate:Number(node.rate),group_ids:node.group_ids.map(Number),route_ids:node.route_ids.map(Number),tags:parse(node.tags,'标签'),excludes:parse(node.excludes,'排除项'),ips:parse(node.ips,'IP 列表'),enabled:node.enabled,show:node.show,machine_id:node.machine_id?Number(node.machine_id):null,parent_id:node.parent_id?Number(node.parent_id):null,transfer_enable:node.transfer_enable===''?null:Number(node.transfer_enable),code:node.code||null,spectific_key:node.spectific_key||null,protocol_settings:parse(node.protocol_settings,'协议配置')};await props.api('server/manage/save',{method:'POST',body});modal.value=false;await load()}catch(e){formError.value=e.message}finally{saving.value=false}}
function newGroup(item=null){Object.assign(group,{id:item?.id||null,name:item?.name||''});formError.value='';formKind.value='group';modal.value=true}
async function saveGroup(){saving.value=true;try{await props.api('server/group/save',{method:'POST',body:{id:group.id||undefined,name:group.name}});modal.value=false;await load()}catch(e){formError.value=e.message}finally{saving.value=false}}
function newRoute(item=null){Object.assign(route,{id:item?.id||null,remarks:item?.remarks||'',match:JSON.stringify(item?.match||[],null,2),action:item?.action||'proxy',action_value:item?.action_value||''});formError.value='';formKind.value='route';modal.value=true}
async function saveRoute(){saving.value=true;try{await props.api('server/route/save',{method:'POST',body:{id:route.id||undefined,remarks:route.remarks,match:parse(route.match,'匹配规则'),action:route.action,action_value:route.action_value||null}});modal.value=false;await load()}catch(e){formError.value=e.message}finally{saving.value=false}}
async function save(){if(formKind.value==='node')return saveNode();if(formKind.value==='group')return saveGroup();return saveRoute()}
async function toggleNode(item,key){try{await props.api('server/manage/update',{method:'POST',body:{id:item.id,[key]:!item[key]}});await load()}catch(e){error.value=e.message}}
async function deleteItem(kind,item){const names={node:item.name,group:item.name,route:item.remarks};if(!window.confirm(`删除${kind==='node'?'节点':kind==='group'?'权限组':'线路规则'}“${names[kind]}”？`))return;const paths={node:'server/manage/drop',group:'server/group/drop',route:'server/route/drop'};try{await props.api(paths[kind],{method:'POST',body:{id:item.id}});await load()}catch(e){error.value=e.message}}
async function nodeAction(action,item){const labels={copy:'复制节点',resetTraffic:'重置该节点流量'};if(!window.confirm(`${labels[action]}：${item.name}？`))return;try{await props.api(`server/manage/${action}`,{method:'POST',body:{id:item.id}});await load()}catch(e){error.value=e.message}}
async function generateEch(item){const publicName=window.prompt(`ECH public_name for ${item.name}:`,'ech.example.com');if(!publicName)return;try{const d=await props.api(`server/manage/generateEchKey?public_name=${encodeURIComponent(publicName)}`);echNode.value=item.name;echKey.value=JSON.stringify(d,null,2)}catch(e){error.value=e.message}}
onMounted(load)
</script>
<template><section class="content-view server-view"><div class="page-title-row"><div><p class="eyebrow">INFRASTRUCTURE / CONTROL</p><h1>{{tab==='nodes'?'节点':tab==='groups'?'权限组':'线路规则'}}<span class="title-period">.</span></h1><p class="page-subtitle">节点协议与传输配置、用户权限组和分流规则</p></div><button class="assign-order-button" @click="tab==='nodes'?newNode():tab==='groups'?newGroup():newRoute()">＋ 新建{{tab==='nodes'?'节点':tab==='groups'?'权限组':'规则'}}</button></div><div class="gift-tabs"><button v-for="[id,label] in tabs" :key="id" :class="{selected:tab===id}" @click="changeTab(id)">{{label}}</button></div><div v-if="error" class="api-error"><span>!</span><div><b>基础设施操作失败</b><p>{{error}}</p></div><button @click="load">重试</button></div>
<div v-if="tab==='nodes'" class="users-table-wrap"><div v-if="loading" class="table-state">正在读取节点…</div><div v-else-if="!nodes.length" class="table-state">暂无节点。</div><table v-else class="users-table server-table"><thead><tr><th>节点</th><th>协议</th><th>接入地址</th><th>倍率</th><th>流量</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="item in nodes" :key="item.id"><td><b>{{item.name}}</b><small class="order-id">ID {{item.id}} · {{(item.groups||[]).map(x=>x.name).join(', ')||'未分组'}}</small></td><td><code class="trade-code">{{item.type}}</code></td><td>{{item.host}}:{{item.port}}</td><td>{{item.rate}}×</td><td>{{traffic(Number(item.u||0)+Number(item.d||0))}}</td><td><div class="status-pair"><button class="user-status status-button" :class="{disabled:!item.show}" @click="toggleNode(item,'show')">{{item.show?'前台':'隐藏'}}</button><button class="user-status status-button" :class="{disabled:!item.enabled}" @click="toggleNode(item,'enabled')">{{item.enabled?'启用':'停用'}}</button></div></td><td><div class="row-actions server-actions"><button @click="editNode(item)">编辑</button><button @click="nodeAction('copy',item)">复制</button><button @click="nodeAction('resetTraffic',item)">重置流量</button><button @click="generateEch(item)">生成 ECH</button><button class="danger-action" @click="deleteItem('node',item)">删除</button></div></td></tr></tbody></table><div v-if="echKey" class="data-panel"><div class="panel-heading"><h2>ECH 密钥 · {{echNode}}</h2><button @click="echKey=''">关闭</button></div><pre class="response-json">{{echKey}}</pre></div></div>
<div v-else-if="tab==='groups'" class="users-table-wrap"><div v-if="loading" class="table-state">正在读取权限组…</div><div v-else-if="!groups.length" class="table-state">暂无权限组。</div><table v-else class="users-table"><thead><tr><th>组名</th><th>用户</th><th>节点</th><th>操作</th></tr></thead><tbody><tr v-for="g in groups" :key="g.id"><td><b>{{g.name}}</b><small class="order-id">ID {{g.id}}</small></td><td>{{g.users_count||0}}</td><td>{{g.server_count||0}}</td><td><div class="row-actions"><button @click="newGroup(g)">编辑</button><button class="danger-action" @click="deleteItem('group',g)">删除</button></div></td></tr></tbody></table></div>
<div v-else class="users-table-wrap"><div v-if="loading" class="table-state">正在读取线路规则…</div><div v-else-if="!routes.length" class="table-state">暂无线路规则。</div><table v-else class="users-table"><thead><tr><th>备注</th><th>动作</th><th>匹配规则</th><th>操作</th></tr></thead><tbody><tr v-for="r in routes" :key="r.id"><td><b>{{r.remarks}}</b><small class="order-id">ID {{r.id}}</small></td><td>{{r.action}} {{r.action_value}}</td><td><code class="trade-code">{{JSON.stringify(r.match)}}</code></td><td><div class="row-actions"><button @click="newRoute(r)">编辑</button><button class="danger-action" @click="deleteItem('route',r)">删除</button></div></td></tr></tbody></table></div><div class="footer-note"><span>XB CONTROL ROOM</span><span>节点传输协议高级选项由 protocol_settings 提供 <i>·</i> JSON 编辑遵循 Xboard 验证规则</span></div>
<div v-if="modal" class="modal-backdrop" @click.self="modal=false"><section class="user-modal server-modal" role="dialog" aria-modal="true"><header class="modal-header"><div><p class="eyebrow">INFRASTRUCTURE / {{formKind.toUpperCase()}}</p><h2>{{formKind==='node'?(node.id?'编辑节点':'新建节点'):formKind==='group'?(group.id?'编辑权限组':'新建权限组'):(route.id?'编辑线路规则':'新建线路规则')}}</h2></div><button class="modal-close" @click="modal=false">×</button></header><form class="user-form" @submit.prevent="save"><template v-if="formKind==='node'"><div class="form-pair"><label>节点名称<input v-model.trim="node.name" required/></label><label>协议类型<select v-model="node.type"><option v-for="type in types" :key="type">{{type}}</option></select></label></div><div class="form-pair"><label>连接地址<input v-model.trim="node.host" required/></label><label>连接端口<input v-model.number="node.port" type="number" required/></label></div><div class="form-pair"><label>服务端口<input v-model.number="node.server_port" type="number" required/></label><label>倍率<input v-model.number="node.rate" type="number" min="0" step="0.01" required/></label></div><div class="form-pair"><label>权限组<select v-model="node.group_ids" multiple class="multi-select"><option v-for="g in groups" :key="g.id" :value="g.id">{{g.name}}</option></select></label><label>线路规则<select v-model="node.route_ids" multiple class="multi-select"><option v-for="r in routes" :key="r.id" :value="r.id">{{r.remarks}}</option></select></label></div><div class="form-pair"><label>机器<select v-model="node.machine_id"><option value="">无关联</option><option v-for="m in machines" :key="m.id" :value="m.id">{{m.name}}</option></select></label><label>绑定代码<input v-model="node.code"/></label></div><label>协议特定键<input v-model="node.spectific_key"/></label><div class="form-pair"><label>标签 JSON<input v-model="node.tags"/></label><label>排除项 JSON<input v-model="node.excludes"/></label></div><label>协议配置 JSON<textarea v-model="node.protocol_settings" rows="10" spellcheck="false"/></label><div class="toggle-row"><label><input v-model="node.enabled" type="checkbox"/> 启用</label><label><input v-model="node.show" type="checkbox"/> 前台显示</label></div></template><template v-else-if="formKind==='group'"><label>权限组名称<input v-model.trim="group.name" required/></label></template><template v-else><label>备注<input v-model.trim="route.remarks" required/></label><div class="form-pair"><label>动作<select v-model="route.action"><option value="block">阻止</option><option value="direct">直连</option><option value="dns">DNS</option><option value="proxy">代理</option></select></label><label>动作参数<input v-model="route.action_value"/></label></div><label>匹配规则 JSON<textarea v-model="route.match" rows="8" required spellcheck="false"/></label></template><p v-if="formError" class="notice">{{formError}}</p><footer class="modal-footer"><button type="button" class="cancel-button" @click="modal=false">取消</button><button class="save-button" :disabled="saving">{{saving?'保存中…':'保存'}}</button></footer></form></section></div></section></template>
